async function getImportUrl() {
  const repoBase = 'https://gcore.jsdelivr.net/gh/kai6666666/battle-dashboard';
  try {
    const response = await fetch('https://api.github.com/repos/kai6666666/battle-dashboard/commits/main');
    if (!response.ok) throw new Error('HTTP ' + response.status);
    const data = await response.json();
    const ref = data?.sha || 'main';
    return repoBase + '@' + ref + '/dist/战斗仪表盘/stable.js';
  } catch {
    return repoBase + '@main/dist/战斗仪表盘/stable.js?t=' + Date.now();
  }
}

const importUrl = await getImportUrl();
await import(importUrl);
